using System.Diagnostics; using System.Net.Http; using System.Net.Http.Json;
namespace ChatVox.Twitch;
public sealed class DeviceCodeClient(HttpClient http){public async Task<DeviceCodeResponse> StartAsync(string clientId,CancellationToken ct)=>await http.PostAsync("https://id.twitch.tv/oauth2/device",new FormUrlEncodedContent([new("client_id",clientId),new("scopes","user:read:chat")]),ct).Result.Content.ReadFromJsonAsync<DeviceCodeResponse>(cancellationToken:ct)??throw new InvalidOperationException("Invalid Twitch device response"); public async Task<TokenResponse> PollAsync(string clientId,DeviceCodeResponse d,CancellationToken ct){var until=DateTimeOffset.UtcNow.AddSeconds(d.ExpiresIn);var delay=Math.Max(1,d.Interval);while(DateTimeOffset.UtcNow<until){await Task.Delay(TimeSpan.FromSeconds(delay),ct);var r=await http.PostAsync("https://id.twitch.tv/oauth2/token",new FormUrlEncodedContent([new("client_id",clientId),new("device_code",d.DeviceCode),new("grant_type","urn:ietf:params:oauth:grant-type:device_code")]),ct);if(r.IsSuccessStatusCode)return await r.Content.ReadFromJsonAsync<TokenResponse>(cancellationToken:ct)??throw new InvalidOperationException("Malformed token response");var body=await r.Content.ReadAsStringAsync(ct);if(body.Contains("authorization_pending"))continue;if(body.Contains("slow_down")){delay+=5;continue;}throw new InvalidOperationException(body.Contains("access_denied")?"Authorization denied":body.Contains("expired_token")?"Authorization expired":"Twitch token request failed");}throw new TimeoutException("Twitch authorization timed out");} public static void Open(DeviceCodeResponse d)=>Process.Start(new ProcessStartInfo(d.VerificationUri){UseShellExecute=true});}
